// Keep only connected accounts on the platforms chosen in the configuration node.
const cfg = $('Configure carousel brand and topics').first().json;
const wanted = String(cfg.platformFilter || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
const accounts = $input.all().map(i => i.json);

const selected = accounts.filter(a => {
  const status = String(a.connectionStatus || 'CONNECTED').toUpperCase();
  const platform = String(a.platform || '').toUpperCase();
  return status === 'CONNECTED' && (wanted.length === 0 || wanted.includes(platform));
});

if (selected.length === 0) {
  throw new Error('No connected accounts matched the platform filter. Check the configuration node and your PostFast connections.');
}

return [{ json: {
  accountIds: selected.map(a => a.id ?? a.socialMediaId)
} }];

// One item per slide, each with a composed image prompt.
const cfg = $('Configure carousel brand and topics').first().json;
const raw = $input.first().json;
let parsed = raw.message?.content ?? raw.output ?? raw;
if (typeof parsed === 'string') parsed = JSON.parse(parsed);
const slides = parsed.slides || [];
if (slides.length === 0) throw new Error('OpenAI returned no slides. Check the prompt output.');

const n = Math.min(slides.length, Number(cfg.slideCount) || 5);
if (n < 2 || n > 8) throw new Error('slideCount must be between 2 and 8 (the upload endpoint issues at most 8 URLs per request).');

return slides.slice(0, n).map((s, i) => ({ json: {
  slideIndex: i,
  imagePrompt: `${cfg.imageStyle}. Carousel slide ${i + 1} of ${n}, portrait format. Render this text large, centered and highly readable on the image. Headline: "${s.heading}". Supporting line: "${s.body}". Scene: ${s.visual}. No watermarks, no logos.`
} }));

// One item per selected account.
const accountIds = $('Select target accounts').first().json.accountIds;
return accountIds.map(id => ({ json: { accountId: id } }));

// Pair every slide image with one upload URL per account and attach the binary.
const accounts = $('Fan out per account').all().map(i => i.json.accountId);
const slides = $('Generate slide images').all();

const flat = [];
for (const it of $('Get upload URLs (PostFast)').all()) {
  const j = it.json;
  if (Array.isArray(j)) flat.push(...j);
  else if (Array.isArray(j.data)) flat.push(...j.data);
  else if (Array.isArray(j.urls)) flat.push(...j.urls);
  else flat.push(j);
}

const need = accounts.length * slides.length;
if (flat.length < need) {
  throw new Error(`Got ${flat.length} upload URLs but need ${need} (${accounts.length} accounts x ${slides.length} slides). Check the Get upload URLs node.`);
}

const out = [];
accounts.forEach((accountId, ai) => {
  slides.forEach((s, si) => {
    const u = flat[ai * slides.length + si];
    out.push({ json: { accountId, slideIndex: si, signedUrl: u.signedUrl, key: u.key }, binary: s.binary });
  });
});
return out;

// One scheduled carousel per account, slides in order via sortOrder.
const caption = $('Write the carousel post').first().json.message.content.caption;
const items = $('Pair slides to upload URLs').all().map(i => i.json);
const when = new Date(Date.now() + 60 * 60 * 1000).toISOString();

const byAccount = {};
for (const it of items) {
  (byAccount[it.accountId] ??= []).push(it);
}

return Object.entries(byAccount).map(([accountId, slides]) => ({ json: {
  socialMediaId: accountId,
  content: caption,
  scheduledAt: when,
  mediaItemsJson: JSON.stringify(
    slides
      .sort((a, b) => a.slideIndex - b.slideIndex)
      .map(s => ({ key: s.key, type: 'IMAGE', sortOrder: s.slideIndex }))
  )
} }));
